fn push_rules_rule_3991(rules: &mut Vec<RubiRule>) {
    rubi_symb!(symbols; a__, b__, e__, f__, m_, n_, x_);
    rules.push(rubi_rule!(
        order: 3991,
        source: "Int[sec[e_.+f_.*x_]^m_.*(a_+b_.*tan[e_.+f_.*x_])^n_,x_Symbol] :=
          Module[{k},
          Int[Sec[e+f*x]^m*Sum[Binomial[n,2*k]*a^(n-2*k)*b^(2*k)*Tan[e+f*x]^(2*k),{k,0,n/2}],x] +
          Int[Sec[e+f*x]^m*Tan[e+f*x]*Sum[Binomial[n,2*k+1]*a^(n-2*k-1)*b^(2*k+1)*Tan[e+f*x]^(2*k),{k,0,(n-1)/2}],x]] /;
        FreeQ[{a,b,e,f},x] && NeQ[a^2+b^2,0] && IntegerQ[(m-1)/2] && IGtQ[n,0]",
        desc: "Decompose the integrand into a sum of simpler integrals.",
        refs: [],
        pattern:  rubi_shared_pattern_43(symbols),
        with: [e__, f__, m_, a__, b__, n_, x_],
        optional: [m_, b__, e__, f__],
        when: {
            freeq!([a__, b__, e__, f__], x_)
                && neq!(a__.pow(2) + b__.pow(2), 0)
                && integerq!((&m_ - 1) / 2)
                && igtq!(n_, 0)
        },
        rhs: {
            let n = integer_i64(&n_).rubi_rhs();
            let angle = &e__ + &f__ * x_;
            let tan = angle.tan();
            let sec_power = angle.sec().pow(&m_);
            let mut even_sum = Atom::num(0);
            for k in 0..=n / 2 {
                let two_k = 2 * k;
                even_sum += rubi_binomial_coefficient(n, two_k).rubi_rhs()
                    * a__.pow(n - two_k)
                    * b__.pow(two_k)
                    * tan.pow(two_k);
            }
            let mut odd_sum = Atom::num(0);
            for k in 0..=(n - 1) / 2 {
                let two_k = 2 * k;
                odd_sum += rubi_binomial_coefficient(n, two_k + 1).rubi_rhs()
                    * a__.pow(n - two_k - 1)
                    * b__.pow(two_k + 1)
                    * tan.pow(two_k);
            }
            let first = rubi_rhs_int(&(&sec_power * even_sum), x_);
            let second = rubi_rhs_int(&(sec_power * tan * odd_sum), x_);
            first + second
        },
    ));
}

