            let recursive_integrand = (&b__ * &d__ + Atom::num(2) * &a__ * &c__ * &f__ + Atom::num(2) * &a__ * &d__ * &f__ * x_) / tan;
            let recursive = rubi_rhs_int(&recursive_integrand, x_);

            rubi_simp(&(-linear.pow(2) / (Atom::num(2) * &d__ * &sum)), x_)
