fn push_rules_rule_4019(rules: &mut Vec<RubiRule>) {
    rubi_symb!(symbols; a__, b__, c__, d__, e__, f__, x_);
    rules.push(rubi_rule!(
        order: 4019,
        source: "Int[(c_.+d_.*tan[e_.+f_.*x_])/Sqrt[a_+b_.*tan[e_.+f_.*x_]],x_Symbol] :=
          With[{q=Rt[a^2+b^2,2]},
          1/(2*q) \\[Star] Int[(a*c+b*d+c*q+(b*c-a*d+d*q)*Tan[e+f*x])/Sqrt[a+b*Tan[e+f*x]],x] -
          1/(2*q) \\[Star] Int[(a*c+b*d-c*q+(b*c-a*d-d*q)*Tan[e+f*x])/Sqrt[a+b*Tan[e+f*x]],x]] /;
        FreeQ[{a,b,c,d,e,f},x] && NeQ[b*c-a*d,0] && NeQ[a^2+b^2,0] && NeQ[c^2+d^2,0] && NeQ[2*a*c*d-b*(c^2-d^2),0] && NiceSqrtQ[a^2+b^2]",
        desc: "Decompose the integrand into a sum of simpler integrals.",
        refs: [],
        pattern:  rubi_shared_pattern_23(symbols),
        with: [c__, d__, e__, f__, a__, b__, x_],
        optional: [c__, d__, b__, e__, f__],
        when: {
            let discriminant = a__.pow(2) + b__.pow(2);
            freeq!([a__, b__, c__, d__, e__, f__], x_)
                && neq!(&b__ * &c__ - &a__ * &d__, 0)
                && neq!(discriminant, 0)
                && neq!(c__.pow(2) + d__.pow(2), 0)
                && neq!(Atom::num(2) * &a__ * &c__ * &d__ - &b__ * (c__.pow(2) - d__.pow(2)), 0)
                && rubi_nice_sqrt_q(&discriminant)
        },
        rhs: {
            let tan = (&e__ + &f__ * x_).tan();
            let denominator = (&a__ + &b__ * &tan).sqrt();
            let q_rt = rubi_rt(&(a__.pow(2) + b__.pow(2)), 2);
            let recursive1_integrand = (&a__ * &c__
                + &b__ * &d__
                + &c__ * &q_rt
                + (&b__ * &c__ - &a__ * &d__ + &d__ * &q_rt) * &tan)
                / &denominator;
            let recursive2_integrand = (&a__ * &c__
                + &b__ * &d__
                - &c__ * &q_rt
                + (&b__ * &c__ - &a__ * &d__ - &d__ * &q_rt) * tan)
                / denominator;
            let recursive1 = rubi_rhs_int(&recursive1_integrand, x_);
            let recursive2 = rubi_rhs_int(&recursive2_integrand, x_);

            rubi_star(Atom::num(1) / (Atom::num(2) * &q_rt), recursive1) + rubi_star(Atom::num(-1) / (Atom::num(2) * q_rt), recursive2)
        },
    ));
}

